    def test_randomizer_fills_empty_slots(self) -> None:
        selected = OrderedDict({"主体": ["成年女性"], "构图视角": []})
        custom_tags: list[str] = []
        settings = {
            "运行时随机模式": "保留已选核心标签",
            "运行时随机强度": "中",
            "核心标签锁定数量": 10,
            "seed": 1,
            "unique_id": "demo",
            "锁定标签白名单": "",
            "随机排除标签": "",
            "随机补充避重缓存": "",
        }
        next_selected, _, generated = randomizer.build_runtime_tags(
            selected,
            custom_tags,
            settings,
            all_tag_groups=lambda: [("主体", 2, ["无", "成年女性", "偶像"]), ("构图视角", 1, ["无", "中景", "近景"])],
            tag_group_index=lambda: {"成年女性": "主体", "偶像": "主体", "中景": "构图视角", "近景": "构图视角"},
            parse_tags=lambda text: [],
            uniq=uniq,
            seed_normalizer=lambda seed: int(seed),
            history_loader=lambda _node_id: [],
            random_module=__import__("random"),
            empty_tag="无",
        )
        self.assertGreaterEqual(len(next_selected["主体"]), 1)
        self.assertEqual(len(next_selected["构图视角"]), 1)
        self.assertTrue(generated)

    def test_randomizer_does_not_fill_all_twenty_expanded_slots(self) -> None:
        options = ["无", *[f"候选{index}" for index in range(1, 31)]]
        base_settings = {
            "运行时随机模式": "全随机",
            "核心标签锁定数量": 0,
            "seed": 19,
            "unique_id": "expanded-slot-random-budget",
            "锁定标签白名单": "",
            "随机排除标签": "",
            "随机补充避重缓存": "",
            "随机主题池": "自动",
        }
        for intensity, expected in (("弱", 1), ("中", 2), ("强", 10), ("强 / 极限拉开", 10)):
            next_selected, _next_custom, generated = randomizer.build_runtime_tags(
                OrderedDict({"主体": []}),
                [],
                {**base_settings, "运行时随机强度": intensity},
                all_tag_groups=lambda: [("主体", 20, options)],
                tag_group_index=lambda: {tag: "主体" for tag in options if tag != "无"},
                parse_tags=lambda _value: [],
                uniq=uniq,
                seed_normalizer=lambda value: int(value),
                history_loader=lambda _node_id: [],
                random_module=random,
                empty_tag="无",
            )
            self.assertEqual(len(next_selected["主体"]), expected)
            self.assertEqual(len(generated), expected)

    def test_randomizer_preserves_limited_core_tags(self) -> None:
        selected = OrderedDict(
            {
                "主体": ["成年女性", "东亚"],
                "构图视角": ["中景"],
                "场景背景": ["校园"],
            }
        )
        custom_tags = ["柔光"]
        settings = {
            "运行时随机模式": "保留已选核心标签",
            "运行时随机强度": "弱",
            "核心标签锁定数量": 2,
            "seed": 1,
            "unique_id": "demo",
            "锁定标签白名单": "校园",
            "随机排除标签": "",
            "随机补充避重缓存": "",
        }
        next_selected, next_custom, generated = randomizer.build_runtime_tags(
            selected,
            custom_tags,
            settings,
            all_tag_groups=lambda: [
                ("主体", 2, ["无", "成年女性", "东亚", "偶像"]),
                ("构图视角", 1, ["无", "中景"]),
                ("场景背景", 2, ["无", "校园", "教室"]),
            ],
            tag_group_index=lambda: {"成年女性": "主体", "东亚": "主体", "偶像": "主体", "中景": "构图视角", "校园": "场景背景", "教室": "场景背景"},
            parse_tags=lambda text: [item.strip() for item in str(text).split(",") if item.strip()],
            uniq=uniq,
            seed_normalizer=lambda seed: int(seed),
            history_loader=lambda _node_id: [],
            random_module=__import__("random"),
            empty_tag="无",
        )
        self.assertEqual(next_selected["主体"], ["成年女性", "东亚"])
        self.assertEqual(next_selected["构图视角"], ["中景"])
        self.assertEqual(next_selected["场景背景"], ["校园", "教室"])
        self.assertEqual(next_custom, [])
        self.assertEqual(generated, ["中景", "教室"])

