    def test_stage_generator_output_contract_matches_ui_slots(self) -> None:
        module = load_stage_prompt_generator_for_integration_test()
        node_class = getattr(module, "QwenTE阶段式提示词生成器")
        self.assertEqual(node_class.RETURN_TYPES, ("STRING", "STRING", "STRING", "STRING", "STRING", "STRING", "STRING", "STRING"))
        self.assertEqual(
            node_class.RETURN_NAMES,
            ("结果全文", "首条正向提示词", "已选标签", "JSON结果", "推荐负面词", "正向提示词合集", "智能文本", "视频提示词"),
        )
        self.assertTrue(node_class.OUTPUT_NODE)
        input_types = node_class.INPUT_TYPES()
        self.assertEqual(input_types["optional"]["参考图片"], ("IMAGE",))
        self.assertIn("图片反推生成", input_types["required"])
        self.assertIn("图片反推模式", input_types["required"])
        for group_name in ("主体", "画面风格", "成人向表达", "光影氛围", "构图视角", "动作姿态", "服装造型", "场景背景", "道具世界观", "技术画质"):
            first_slot = input_types["required"][f"{group_name}标签1"]
            last_slot = input_types["required"][f"{group_name}标签20"]
            expected_slot = ("STRING", {"default": "无", "multiline": False, "advanced": True})
            self.assertEqual(first_slot, expected_slot)
            self.assertEqual(last_slot, expected_slot)
            self.assertNotIn(f"{group_name}标签21", input_types["required"])

        serialized = json.dumps(input_types, ensure_ascii=False).encode("utf-8")
        self.assertLess(len(serialized), 256 * 1024)

