    def test_natural_language_validator_rejects_tag_chains(self) -> None:
        natural = (
            "电影感影像，画面以成年女性为核心，主体位于雨夜街头并自然走动。"
            "镜头采用全景构图，以霓虹逆光塑造空间层次，最终画面保持材质可信和视觉流动。"
        )
        tag_chain = "成年女性, 电影写实, 雨夜街头, 霓虹逆光, 全景全身, 自然行走, 高细节, 清晰对焦"
