    def test_model_refiner_retries_transient_timeout_and_recovers_without_skill_fallback(self) -> None:
        class FlakyLLM:
            def __init__(self):
                self.calls = 0

            def create_chat_completion(self, *args, **kwargs):
                self.calls += 1
                if self.calls == 1:
                    raise TimeoutError("The read operation timed out")
                return {
                    "choices": [
                        {
                            "message": {
                                "content": (
                                    "成年女性在雨夜站台听见远处列车声，因此停下脚步回望。"
                                    "她的情绪由等待转为警觉，霓虹反射随着动作掠过衣料和湿地面，"
                                    "镜头最终定格在列车尚未进入画面的瞬间。"
                                )
                            }
                        }
                    ]
                }

        llm = FlakyLLM()
        settings = {
            "提示词语言": "纯中文",
            "主体类型": "人物角色",
            "主体类型解析结果": "人物角色",
            "模型来源": "API接口",
            "模型调用基础来源": "API接口",
            "模型瞬时重试次数": 1,
        }
        result = model_refiner.maybe_model_refine(
            llm,
            "成年女性在雨夜站台等待，霓虹逆光，全景全身，高细节",
            settings,
            chat_completion=lambda model, messages, params: model.create_chat_completion(
                messages=messages,
                **params,
            ),
            clean_think_text=lambda value: value,
        )
        self.assertEqual(llm.calls, 2)
        self.assertIn("因此", result)
        self.assertEqual(settings.get("模型传输重试次数"), 1)
        self.assertEqual(settings.get("模型活动回退数量", 0), 0)
        self.assertTrue(any("已恢复" in note for note in settings.get("推理纠偏说明", [])))

    def test_model_refiner_honors_bounded_api_retry_after(self) -> None:
        class RateLimitError(RuntimeError):
            status = 429
            retry_after = 1.25

        class RateLimitedLLM:
            def __init__(self):
                self.calls = 0

            def create_chat_completion(self, *args, **kwargs):
                self.calls += 1
                if self.calls == 1:
                    raise RateLimitError("HTTP 429 Too Many Requests")
                return {
                    "choices": [{"message": {"content": (
                        "成年女性在雨夜站台听见列车声，因此停下脚步回望。"
                        "霓虹反射沿湿地面延伸，镜头最终停在她警觉的动作上。"
                    )}}]
                }

        llm = RateLimitedLLM()
        settings = {
            "提示词语言": "纯中文",
            "主体类型": "人物角色",
            "主体类型解析结果": "人物角色",
            "模型来源": "API接口",
            "模型调用基础来源": "API接口",
            "模型瞬时重试次数": 1,
        }
        with mock.patch.object(model_refiner.time, "sleep") as sleep:
            result = model_refiner.maybe_model_refine(
                llm,
                "成年女性在雨夜站台等待，霓虹逆光，全景全身，高细节",
                settings,
                chat_completion=lambda model, messages, params: model.create_chat_completion(
                    messages=messages,
                    **params,
                ),
                clean_think_text=lambda value: value,
            )

        self.assertEqual(llm.calls, 2)
        sleep.assert_called_once_with(1.25)
        self.assertIn("因此", result)
        self.assertEqual(settings.get("模型传输重试次数"), 1)

